const text = msg.payload.text;
if (!text) return msg;

const regex = /Posisjonen til delhendelsen '(.+?)' ble endret til '([0-9.]+):([0-9.]+)' \(var: '(.+?):(.+?)'\)/s;
const match = text.match(regex);

if (match) {
    const name = match[1];
    const lng = parseFloat(match[2]);
    const lat = parseFloat(match[3]);

    const connection_name = msg.metadata.connection_name;
    const source_id = msg.metadata.source.identifier;

    const conns = global.get("parat_bridge.connections") || {};
    const client = conns[connection_name] && conns[connection_name].clients && conns[connection_name].clients[source_id];
    const positions = (client && client.client_specific && client.client_specific.delhendelse_positions) || [];

    const existingIndex = positions.findIndex(p => p.name === name);
    if (existingIndex >= 0) {
        positions[existingIndex].lat = lat;
        positions[existingIndex].lng = lng;
    } else {
        positions.push({ name, lat, lng });
    }

    const key = `parat_bridge.connections.${connection_name}.clients.${source_id}.client_specific.delhendelse_positions`;
    global.set(key, positions);
    // Only trigger geo POST for the last position event per delhendelse
    // (flagged by initial fetch pipeline). Ongoing polling has no flag,                                                                                            
    // so undefined !== false passes through normally.                                                                                                              
    if (msg.payload._is_last_geo !== false) {
        msg.metadata.geo = { lat, lng, name };
    }
}

return msg;
